fields.InputDefinition:
{
  "goal": "Open the 'Members' entity via the LEFT sidebar 'Search entities...' box (type 'Members', click the exact match). Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Open a member row, then 'Open Full Record' to view it in read mode. Locate an email-typed field (e.g. Email) or a URL/website-typed field. When such a field HAS a value it should render as a styled clickable hyperlink — an email with an envelope icon (mailto) or a URL with an external-link arrow icon — rather than as plain text. Success is at least one populated email- or URL-typed field rendering as a styled link with the appropriate icon; if every such field on the record is empty, seeing the read-mode form render cleanly with those fields shown as empty is an acceptable pass.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "A populated email field renders as a clickable link with an envelope icon, OR a populated URL field renders as a link with an external-link icon",
    "The linkified value is presented as a styled hyperlink not plain unstyled text (OR all email/URL fields on the record are empty and render cleanly)",
    "No error messages, blank screens, or crash pages"
  ]
}
